head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST60202";
scwin.xmlHttp = undefined;
scwin.cnt = 0;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60202.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    const searchForm = $('#searchForm');
    $c.util.getComponent("ipt_method").setValue("searchReportName");
    $c.util.getComponent("ipt_forward").setValue("searchReportName");
    $c.util.getComponent('slc_classCd').setValue("03");
    await scwin.getReason($c.util.getComponent('slc_classCd'));
    scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60202.onpageload' }); }
};

// [A] 초기 목록 미해결 — jlddst60202: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60202.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name footGo_onclick
 * @description footGo 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.footGo_onclick = async function(e){
    try {
        await scwin.getReason($c.util.getComponent('slc_classCd')); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60202.footGo_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = function(e){
    try {
        scwin.fnSearchInit(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60202.btn_fnSearchInit_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    try { return await $c.data.downFile("/common/reportname.do", "", ($c.util.getComponent("dma_fnSearchAjaxsubmitReq") ? $c.util.getComponent("dma_fnSearchAjaxsubmitReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_getReason_rawxhr
 * @description get Reason rawxhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_getReason_rawxhr = async function () {
    try { return await $c.data.downFile("/common/reportname.do?method=getReasonList&classCd=", "", {}); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name createXMLHttpRequest
 * @description create XMLHttp Request 처리
 * @returns {void}
 * @hidden N
 */
scwin.createXMLHttpRequest = function () {
    let xmlHttp = null;
    if (XMLHttpRequest) {
        xmlHttp = new XMLHttpRequest();
    }
    return xmlHttp;
};

/**
 * @method
 * @name getReason
 * @description get Reason 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getReason = async function (obj) {
    const idx = obj.getSelectedIndex();
    const classCd = obj[idx].value;
    if (classCd === "") {
        $c.util.getComponent('slc_reasonCd').removeAll();
        $c.util.getComponent('slc_reasonCd').options.add(new Option('전체', ''));
        return;
    }
    await scwin.tx_getReason_rawxhr();
};

/**
 * @method
 * @name handleStateChange
 * @description handle State Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.handleStateChange = function () {
    if (scwin.xmlHttp.readyState === 4) {
        if (scwin.xmlHttp.status === 200) {
            scwin.updateSelectBox();
        }
    }
};

/**
 * @method
 * @name updateSelectBox
 * @description update Select Box 처리
 * @returns {void}
 * @hidden N
 */
scwin.updateSelectBox = function () {
    const obj = $c.util.getComponent('slc_reasonCd');
    const responseXML = scwin.xmlHttp.responseXML;
    scwin.clearSelectBox(obj);
    scwin.updateList(obj, responseXML);
};

/**
 * @method
 * @name updateList
 * @description update List 처리
 * @param {Object} obj 컴포넌트
 * @param {*} element element
 * @returns {void}
 * @hidden N
 */
scwin.updateList = function (obj, element) {
    const nodeList = element.getElementsByTagName("item");
    let node = null;
    let name = null;
    let value = null;
    let i = 0;
    if (i < nodeList.length) {
        obj.options[0] = new Option('전체', '');
    }
    for (let i = 0; i < nodeList.length; i++) {
        node = nodeList[i];
        name = node.getElementsByTagName("name")[0].firstChild.nodeValue;
        value = node.getElementsByTagName("value")[0].firstChild.nodeValue;
        obj.options[i+1] = new Option(value, name);
    }
    scwin.delErrTrdRlf();
};

/**
 * @method
 * @name clearSelectBox
 * @description clear Select Box 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.clearSelectBox = function (obj) {
    for (let i = 0; i < obj.options.length; i++) {
        obj.options[i] = null;
    }
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchInit = function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearch = function () {
    const searchForm = $('#searchForm');
    $c.util.getComponent("ipt_reportName").setValue(encodeURI(document.searchForm.find('input:text[name=ipt_reportNameTmp]').val()));
    document.searchForm.ajaxSubmit({ ajaxUrl: '/common/reportname.do', ajaxCallBack: scwin.fnSearchCallBack });
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
    scwin.onlyErrTrdRlf();
};

/**
 * @method
 * @name setReportNameInfo
 * @description set Report Name Info 처리
 * @param {String} formCd formCd
 * @param {String} formNm formNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setReportNameInfo = async function (formCd, formNm) {
    try {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setReportNameInfo === 'function' ? (scwin.openerScwin()).setReportNameInfo(formCd, formNm) : void 0), $c.win.closePopup([formCd, formNm]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jlddst60202' });
        await $c.win.alert("<ERROR>\n\n" + "부모창에 접근이 안되는데요? \n\n");
    }
};

/**
 * @method
 * @name onlyErrTrdRlf
 * @description only Err Trd Rlf 처리
 * @returns {void}
 * @hidden N
 */
scwin.onlyErrTrdRlf = function () {
    $c.util.getComponent('slc_reasonCd').setValue("62");
    if (scwin.cnt < 1) {
        scwin.fnSearch();
    }
    scwin.cnt++;
    (($c.util.getComponent('footGo')) && ($c.util.getComponent('footGo')).setDisabled ? ($c.util.getComponent('footGo')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    $("#classCd option").not(":selected").remove();
    $("#slc_reasonCd option").not(":selected").remove();
};

/**
 * @method
 * @name delErrTrdRlf
 * @description del Err Trd Rlf 처리
 * @returns {void}
 * @hidden N
 */
scwin.delErrTrdRlf = function () {
    $("#slc_reasonCd option[value='62']").remove();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
